121	// 旧版登记结束在月底，但交接点起必须按被替代后的实际结束时间拒绝：
122	// 即使登记结束尚未到达，引用旧版也得到 version_expired 而非 total_overflow。
123	func TestOverflowOldVersionRejectedByEffectiveEndNotRegisteredEnd(t *testing.T) {
