144		// 交接点之后、登记结束（3 月 31 日）之前：按登记结束看似仍在有效期内，
145		// 但必须按实际结束时间拒绝。
146		setNow(time.Date(2026, 3, 20, 12, 0, 0, 0, time.UTC))
147		req := QuoteRequest{
148			RequestID: "overflow-old-after-handoff",
149			ItemID:    "seat",
150			VersionID: "seat-v1",
151			Quantity:  overflowQuantity,
152		}
153		out, err := b.Quote(req)
154		if err != nil {
