183			req := QuoteRequest{
184				RequestID: fmt.Sprintf("no-switch-overflow-%d", i),
185				ItemID:    "seat",
186				VersionID: c.versionID,
187				Quantity:  overflowQuantity,
188			}
189			out, err := b.Quote(req)
190			if err != nil {
191				t.Fatalf("%s: 受理后的拒绝不应返回 error: %v", c.name, err)
192			}
193			if out.Confirmed {
194				t.Fatalf("%s: 不能换用其他版本确认: %+v", c.name, out)
195			}
196			if out.Reason != c.reason {
197				t.Fatalf("%s: 拒绝原因=%q, want %q", c.name, out.Reason, c.reason)
198			}
199			if out.Request.VersionID != c.versionID {
200				t.Fatalf("%s: 来源必须保留指定版本 %q: %+v", c.name, c.versionID, out.Request)
201			}
202			if out.UnitPrice != 0 || out.Total != 0 {
203				t.Fatalf("%s: 拒绝结果金额应为零: 单价=%d 总价=%d", c.name, out.UnitPrice, out.Total)
204			}
205		}
206	}
