func fixedClock(start time.Time) (func() time.Time, func(time.Time)) {
	var mu sync.Mutex
	cur := start
	return func() time.Time {
			mu.Lock()
			defer mu.Unlock()
			return cur
		}, func(t time.Time) {
			mu.Lock()
			defer mu.Unlock()
			cur = t
		}
}

